package foodchain

import (
	"fmt"
	"strings"
)

var animals = []string{"fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"}

var comments = map[string]string{
	"fly":    "I don't know why she swallowed the fly. Perhaps she'll die.",
	"spider": "It wriggled and jiggled and tickled inside her.",
	"bird":   "How absurd to swallow a bird!",
	"cat":    "Imagine that, to swallow a cat!",
	"dog":    "What a hog, to swallow a dog!",
	"goat":   "Just opened her throat and swallowed a goat!",
	"cow":    "I don't know how she swallowed a cow!",
	"horse":  "She's dead, of course!",
}

const flyLine = "I don't know why she swallowed the fly. Perhaps she'll die."

// Verse returns the lyrics for the given verse (1-8).
func Verse(v int) string {
	var b strings.Builder
	animal := animals[v-1]
	fmt.Fprintf(&b, "I know an old lady who swallowed a %s.\n", animal)
	fmt.Fprintf(&b, "%s\n", comments[animal])
	for i := v - 2; i >= 0; i-- {
		suffix := ""
		if animals[i] == "spider" {
			suffix = " that wriggled and jiggled and tickled inside her"
		}
		fmt.Fprintf(&b, "She swallowed the %s to catch the %s%s.\n", animal, animals[i], suffix)
	}
	if animal != "horse" {
		fmt.Fprintf(&b, "%s", flyLine)
	}
	return b.String()
}

// Verses returns the lyrics for verses start through end, inclusive.
func Verses(start, end int) string {
	verses := make([]string, 0, end-start+1)
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

// Song returns the complete song.
func Song() string {
	return Verses(1, len(animals))
}

